-- Venue Live Guest "Hari Pramuka". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara pramuka), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'pramuka', 'Hari Pramuka (panggung perkemahan)', 'pramuka', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 113, 'center 38%',
  $t${"name":"Pramuka","orn":"diamond","ui":{"ivory":"#FFF8EC","white":"#FFFFFF","soft":"#F1E4D0","soft2":"#D2B48C","accent":"#7B4A2A","deep":"#4A2A18","ink":"#2E1A10","mute":"#8A6F5C","line":"#E6D5BE","serif":"\"Cormorant Garamond\",serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Cormorant Garamond\",serif","it":0,"paper":"#FFFBF2","ink":"#2E1A10","accent":"#7B4A2A","gold":"#D4A017","leaf":"#F1E4D0","hbg":"rgba(255,248,236,.94)","hline":"#D2B48C","motif":"diamond"},"hud":{"bg":"rgba(74,42,24,.86)","acc":"#FFE08A","on":"#2E1A10"},"scr":{"wine":"#4A2A18","veil":"255,248,236"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'pramuka');
update public.live_venues set decor = $d${"speakers":{"url":"/assets/live-decor/pramuka/speakers.webp"},"rope":{"url":"/assets/live-decor/pramuka/rope.webp","w":2.0},"stall_snacks":{"url":"/assets/live-decor/pramuka/stall_snacks.webp"},"stall_candy":{"url":"/assets/live-decor/pramuka/stall_candy.webp"},"stall_drinks":{"url":"/assets/live-decor/pramuka/stall_drinks.webp","w":4.8},"photobooth":{"url":"/assets/live-decor/pramuka/photobooth.webp","w":5.6},"claw":{"url":"/assets/live-decor/pramuka/claw.webp","w":4.4},"arch":{"url":"/assets/live-decor/pramuka/arch.webp"},"fountain":{"url":"/assets/live-decor/pramuka/fountain.webp","w":5.8},"sign":{"url":"/assets/live-decor/pramuka/sign.webp","w":1.2},"easel":{"url":"/assets/live-decor/pramuka/easel.webp","w":2.8,"x":4.6,"z":8.2},"gifts":{"url":"/assets/live-decor/pramuka/gifts.webp"},"table":{"url":"/assets/live-decor/pramuka/table.webp"},"lamp":{"url":"/assets/live-decor/pramuka/lamp.webp","w":0.9},"banner":{"url":"/assets/live-decor/pramuka/banner.webp","w":1.5},"balloons":{"url":"/assets/live-decor/pramuka/balloons.webp"},"planter":{"url":"/assets/live-decor/pramuka/planter.webp"},"bush":{"url":"/assets/live-decor/pramuka/bush.webp"},"av_host":{"url":"/assets/live-decor/pramuka/av_host.webp","name":"Pramuka Baret"},"av_l1":{"url":"/assets/live-decor/pramuka/av_l1.webp","name":"Pramuka Baret"},"av_l2":{"url":"/assets/live-decor/pramuka/av_l2.webp","name":"Pramuka Kacamata"},"av_l3":{"url":"/assets/live-decor/pramuka/av_l3.webp","name":"Pramuka Blangkon"},"av_l4":{"url":"/assets/live-decor/pramuka/av_l4.webp","name":"Pramuka Pembawa Bendera"},"av_p1":{"url":"/assets/live-decor/pramuka/av_p1.webp","name":"Pramuka Hijab Cokelat"},"av_p2":{"url":"/assets/live-decor/pramuka/av_p2.webp","name":"Pramuka Kepang"},"av_p3":{"url":"/assets/live-decor/pramuka/av_p3.webp","name":"Pramuka Hijab Krem"}}$d$::jsonb, background_url = '/assets/live-decor/pramuka/painting.webp', active = true, updated_at = now() where key = 'pramuka';
